const { readState, writeState } = require('./backplane');

function claimJob(jobId, workerId) {
  const s = readState();
  const job = s.jobs[jobId];
  if (!job) throw new Error('unknown job: ' + jobId);
  job.owner = workerId;
  job.status = 'running';
  writeState(s);
  return job;
}

function listRunningJobs() {
  const s = readState();
  return Object.keys(s.jobs).filter((id) => s.jobs[id].status === 'running');
}

module.exports = { claimJob, listRunningJobs };

